void setup() {
  Serial.begin(115200);  // baud rate must match Serial Monitor
  Serial.println("Boot complete");
}

void loop() {
  // Send structured CSV data
  float temp = readTemp();
  int light = analogRead(A0);
  Serial.print(millis()); Serial.print(",");
  Serial.print(temp);    Serial.print(",");
  Serial.println(light);
  delay(500);
}

// Read serial command from PC
void serialEvent() {
  if (Serial.available()) {
    char cmd = Serial.read();
    if (cmd == 'L') digitalWrite(13, HIGH);
    if (cmd == 'l') digitalWrite(13, LOW);
  }
}
